package dev.sablelife.testing;
import dev.sablelife.module.*;
import dev.sablelife.heart.HeartBlockEntity;
import dev.sablelife.attack.ModuleShot;
import net.minecraft.core.Direction;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.entity.Display;
import net.minecraft.world.item.*;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.gametest.*;
import java.util.*;
@GameTestHolder("sablelife_summon_tests") @PrefixGameTestTemplate(false)
public final class SummonFormationGameTests {
 private static HeartBlockEntity core(GameTestHelper h){var c=SlashGuardGameTests.core(h);var pin=c.modules().add("hover_anchor");pin.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.UP)));pin.edit("hoverRotation",1,"");return c;}
 private static VirtualModule weapon(HeartBlockEntity c){var a=c.modules().add("gun");a.edit("enabled",0,"");a.edit("speed",.5,"");a.edit("range",1,"");a.edit("interval",1000,"");var m=c.modules().add("summoned_weapon");m.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.NORTH)));m.projectileItem(new ItemStack(Items.CROSSBOW),c.getLevel().registryAccess());m.summonAttack(a.id());m.edit("summonCount",3,"");m.edit("summonFormation",1,"");m.edit("summonSpacing",2,"");m.edit("summonDuration",100,"");return m;}
 @GameTest(template="combat",batch="summon_shapes") public static void EightFormationsMatchHomingAndSingleStaysAtCenter(GameTestHelper h){var c=core(h);var m=weapon(c);var homing=new VirtualModule("homing");homing.anchors(m.anchors());homing.edit("homingCount",5,"");homing.edit("homingOffset",3,"");homing.edit("homingFan",120,"");homing.edit("homingRotation",27,"");homing.edit("homingVerticalRotation",35,"");m.edit("summonCount",5,"");m.edit("summonRadius",3,"");m.edit("summonSpacing",6*Math.sin(Math.PI/3)/4,"");m.edit("summonFormationRoll",27,"");m.edit("summonFormationYaw",35,"");var center=ModuleSummonedWeapon.position(c,m);var hcenter=ModuleCombat.origin(c,homing,true).add(ModuleCombat.direction(c,homing).scale(3)).add(0,homing.value("homingHeight"),0);
  for(int shape=0;shape<8;shape++){m.edit("summonFormation",shape,"");homing.edit("homingPlane",shape,"");var actual=ModuleSummonedWeapon.formation(c,m);var old=ModuleHoming.formation(c,homing);h.assertTrue(actual.size()==5,"Wrong formation count");for(int i=0;i<5;i++)h.assertTrue(actual.get(i).subtract(center).distanceToSqr(old.get(i).subtract(hcenter))<1e-8,"Homing/summon shape differs: "+shape);m.edit("summonCount",1,"");h.assertTrue(ModuleSummonedWeapon.formation(c,m).equals(List.of(center)),"Single formation gained offset");m.edit("summonCount",5,"");}h.succeed();}
 @GameTest(template="combat",batch="summon_spacing") public static void SpacingRotationAndLegacyPresetSettingsRemainIndependent(GameTestHelper h){var c=core(h);var m=weapon(c);m.edit("summonCount",5,"");var points=ModuleSummonedWeapon.formation(c,m);for(int i=1;i<5;i++)h.assertTrue(Math.abs(points.get(i).distanceTo(points.get(i-1))-2)<1e-8,"Line spacing changed with count");h.assertTrue(points.get(2).distanceToSqr(ModuleSummonedWeapon.position(c,m))<1e-8,"Line is not centered");m.edit("displayRotX",90,"");h.assertTrue(ModuleSummonedWeapon.formation(c,m).equals(points),"Model rotation changed formation");m.edit("summonFormationRoll",90,"");var turned=ModuleSummonedWeapon.formation(c,m);h.assertTrue(Math.abs(turned.get(0).y-turned.get(4).y)>7.9,"Plane rotation failed");m.edit("summonCount",100,"");h.assertTrue(ModuleSummonedWeapon.formation(c,m).size()==32,"Count not bounded");var copy=ModulePreset.create(m.save());h.assertTrue(copy.value("summonCount")==32&&copy.value("summonSpacing")==2&&copy.value("summonFormationRoll")==90,"Preset lost formation");var legacy=m.save();for(String key:List.of("summonCount","summonFormation","summonRadius","summonSpacing","summonFan","summonFormationRoll","summonFormationYaw","summonDeployGap"))legacy.getCompound("Settings").remove(key);h.assertTrue(VirtualModule.load(legacy).value("summonCount")==1,"Legacy module spawned multiple weapons");h.succeed();}
 @GameTest(template="combat",batch="summon_independent_members") public static void ThreeMembersFireFromDistinctMuzzlesWithOriginalSourceCredit(GameTestHelper h){var c=core(h);var m=weapon(c);c.tryActivate(TestActors.creative(h.getLevel()));c.modules().tick(c);var frames=c.modules().summonedWeapons.frames(m.id());var origin=ModuleArena.corePosition(c);var shots=h.getLevel().getEntitiesOfClass(ModuleShot.class,new AABB(origin,origin).inflate(16)).stream().filter(e->e.getPersistentData().hasUUID("SableLifeAttackOwner")&&e.getPersistentData().getUUID("SableLifeAttackOwner").equals(c.creatureId())).toList();h.assertTrue(frames.size()==3&&shots.size()==3,"Members shared one attack clock");for(var frame:frames)h.assertTrue(shots.stream().anyMatch(s->s.position().distanceToSqr(frame.muzzle())<1e-8&&s.getPersistentData().getUUID(dev.sablelife.attack.AttackHitCredit.MODULE).equals(m.summonAttackId())),"Muzzle or hit source was not retained");shots.forEach(net.minecraft.world.entity.Entity::discard);c.modules().summonedWeapons.clear();h.succeed();}
 @GameTest(template="combat",batch="summon_stagger",timeoutTicks=30) public static void StaggeredMembersReceiveFullIndividualLifetimes(GameTestHelper h){var c=core(h);var m=weapon(c);m.edit("summonDeployGap",3,"");m.edit("summonDuration",5,"");c.tryActivate(TestActors.creative(h.getLevel()));c.modules().tick(c);h.assertTrue(c.modules().summonedWeapons.snapshot(m.id(),c).getInt("ActiveCount")==1,"Staggered group spawned all at once");
  h.runAfterDelay(4,()->{var s=c.modules().summonedWeapons.snapshot(m.id(),c);h.assertTrue(s.getInt("Spawned")==2&&s.getInt("PendingCount")==1,"Second deployment timing wrong");});
  h.runAfterDelay(10,()->{var s=c.modules().summonedWeapons.snapshot(m.id(),c);h.assertTrue(s.getInt("Spawned")==3&&s.getInt("ActiveCount")==1&&!s.getBoolean("Finished"),"Late member lost its full lifetime");});
  h.runAfterDelay(14,()->{var s=c.modules().summonedWeapons.snapshot(m.id(),c);h.assertTrue(s.getBoolean("Finished")&&s.getInt("ActiveCount")==0&&s.getInt("PendingCount")==0,"Group respawned or left active members");h.succeed();});}
 @GameTest(template="combat",batch="summon_cancel_queue",timeoutTicks=35) public static void TriggerLossKeepsMembersAndPendingDeployments(GameTestHelper h){var c=core(h);var m=weapon(c);m.edit("summonCount",5,"");m.edit("summonDuration",40,"");m.edit("summonDeployGap",10,"");c.tryActivate(TestActors.creative(h.getLevel()));c.modules().tick(c);var p=ModuleSummonedWeapon.position(c,m);h.runAfterDelay(3,()->m.edit("enabled",0,""));h.runAfterDelay(25,()->{h.assertTrue(c.modules().summonedWeapons.snapshot(m.id(),c).getInt("Spawned")==3&&c.modules().summonedWeapons.snapshot(m.id(),c).getInt("PendingCount")==2,"Trigger loss cancelled deployment queue");c.forceDeath();h.assertTrue(c.modules().summonedWeapons.snapshot(m.id(),c).isEmpty(),"Death retained deployed weapons");h.succeed();});}
 @GameTest(template="combat",batch="summon_delayed_world",timeoutTicks=25) public static void DelayedWorldMembersKeepTriggerPositionsWhileFollowGroupMoves(GameTestHelper h){var c=core(h);var follow=weapon(c);follow.edit("summonDeployGap",3,"");var fixed=c.modules().copy(follow.id());fixed.edit("summonPosition",1,"");var locked=ModuleSummonedWeapon.formation(c,fixed);c.tryActivate(TestActors.creative(h.getLevel()));c.modules().tick(c);h.runAfterDelay(1,()->{follow.edit("displayY",5,"");fixed.edit("displayY",5,"");});h.runAfterDelay(8,()->{var moving=c.modules().summonedWeapons.frames(follow.id());var world=c.modules().summonedWeapons.frames(fixed.id());var expected=ModuleSummonedWeapon.formation(c,follow);h.assertTrue(moving.size()==3&&world.size()==3,"Delayed members missing");for(int i=0;i<3;i++)h.assertTrue(moving.get(i).item().distanceToSqr(expected.get(i))<1e-7&&world.get(i).item().distanceToSqr(locked.get(i))<1e-7,"Follow/world delayed formation drifted");c.modules().summonedWeapons.clear();h.succeed();});}
}
